#![allow(clippy::unwrap_used)]
mod support;
use support::*;
use vw_core::*;
fn temp()->tempfile::TempDir{if cfg!(target_os="android"){tempfile::tempdir_in(std::env::current_dir().unwrap()).unwrap()}else{tempfile::tempdir().unwrap()}}
fn request(info:ProjectInfo)->DisplayColorRequest{DisplayColorRequest{binding:WorkflowBinding{project_id:info.project_id,document_id:id(2),host_seq:info.host_seq,state_hash:info.state_hash},region:Some(DisplayRegion{x:2,y:3,width:8,height:7}),space:DisplayColorSpace::DisplayP3,assume_untagged_srgb:true,allow_display_depth_reduction:true,memory_budget_bytes:256*1024*1024}}
#[tokio::test]async fn original_display_is_exact_revision_bound_and_does_not_mutate(){let dir=temp();let p=create_image_project(create(&dir.path().join("project")),cancel()).await.unwrap();let info=p.info(cancel()).await.unwrap();let r=request(info.clone());let out=p.display_original(r,cancel()).await.unwrap();assert_eq!(out.binding.state_hash,info.state_hash);assert_eq!((out.region.x,out.region.y,out.rgba.len()),(2,3,8*7*4));assert!(out.assumed_srgb);let after=p.info(cancel()).await.unwrap();assert_eq!((after.host_seq,after.state_hash),(info.host_seq,info.state_hash));p.close_session().await.unwrap();}
#[tokio::test]async fn stale_and_cancelled_queries_do_not_return_pixels(){let dir=temp();let p=create_image_project(create(&dir.path().join("project")),cancel()).await.unwrap();let mut r=request(p.info(cancel()).await.unwrap());r.binding.state_hash="1".repeat(64);assert!(matches!(p.display_original(r.clone(),cancel()).await,Err(DisplayColorError::Stale)));let c=cancel();c.cancel();assert!(matches!(p.display_original(r,c).await,Err(DisplayColorError::Cancelled)));p.close_session().await.unwrap();}
#[tokio::test]async fn display_refuses_small_budget_and_untagged_without_consent(){let dir=temp();let p=create_image_project(create(&dir.path().join("project")),cancel()).await.unwrap();let mut r=request(p.info(cancel()).await.unwrap());r.assume_untagged_srgb=false;assert!(matches!(p.display_original(r.clone(),cancel()).await,Err(DisplayColorError::Untagged)));r.assume_untagged_srgb=true;r.memory_budget_bytes=8*1024*1024;assert!(matches!(p.display_original(r,cancel()).await,Err(DisplayColorError::Memory{..})));p.close_session().await.unwrap();}
#[tokio::test]async fn altered_same_length_source_is_rejected_before_codec_and_small_budget_before_source_hash(){let dir=temp();let root=dir.path().join("project");let options=create(&root);let original=options.source.clone();let asset=vw_model::AssetId::hash(&original);let p=create_image_project(options,cancel()).await.unwrap();let r=request(p.info(cancel()).await.unwrap());let path=vw_store::BlobStore::new(&root).unwrap().path(&asset).unwrap();let mut corrupt=original;corrupt[0]^=1;std::fs::write(path,&corrupt).unwrap();assert!(matches!(p.display_original(r.clone(),cancel()).await,Err(DisplayColorError::Storage)));let mut small=r;small.memory_budget_bytes=8*1024*1024;assert!(matches!(p.display_original(small,cancel()).await,Err(DisplayColorError::Memory{..})));p.close_session().await.unwrap();}
#[tokio::test]async fn closed_session_and_changed_revision_cannot_supply_a_derivative(){let dir=temp();let p=create_image_project(create(&dir.path().join("project")),cancel()).await.unwrap();let r=request(p.info(cancel()).await.unwrap());let gesture=p.clone().begin_stroke(stroke()).await.unwrap();gesture.append_samples(batch()).await.unwrap();gesture.commit(cancel()).await.unwrap();assert!(matches!(p.display_original(r.clone(),cancel()).await,Err(DisplayColorError::Stale)));p.close_session().await.unwrap();assert!(matches!(p.display_original(r,cancel()).await,Err(DisplayColorError::Closed)));}
